'use strict';
const sections=[['welcome','01','Orientation'],['sound','02','Sound & confidence'],['language','03','Language toolkit'],['identity','04','Your introduction'],['drills','05','Guided exercises'],['listening','06','Listening & reading'],['scenarios','07','Workplace dialogues'],['writing','08','Writing & speaking'],['rehearsal','09','Practice simulation']];
const $=s=>document.querySelector(s), escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={visited:['welcome'],done:{},answers:{},profile:{role:'',sector:'',duty:'',other:'',context:'current',company:''},voice:'',accent:'en-GB',fr:true,showTranscript:{},notes:''};
try{const saved=JSON.parse(localStorage.getItem('veronique-lilate-part1-v2')||'null');if(saved)state={...state,...saved,profile:{...state.profile,...saved.profile}}}catch{}
const save=()=>{try{localStorage.setItem('veronique-lilate-part1-v2',JSON.stringify(state))}catch{}};
const voices=()=>('speechSynthesis' in window)?window.speechSynthesis.getVoices():[];
let activeAudio=null;
function halt(){if('speechSynthesis' in window)speechSynthesis.cancel();if(activeAudio){activeAudio.pause();activeAudio=null}}
function voiceQuality(v){let x=(v.name+' '+v.voiceURI).toLowerCase();return (/natural|neural|premium|enhanced|online/.test(x)?100:0)+(/microsoft|google|apple|samantha|daniel|serena|aria|jenny|sonia|ava/.test(x)?60:0)+(v.lang===state.accent?25:0)+(v.localService?-5:6)}
function suitableVoices(){return voices().filter(v=>/^en[-_]/i.test(v.lang)).sort((a,b)=>voiceQuality(b)-voiceQuality(a));}
function speak(text){halt();if(!('speechSynthesis' in window)){notify('Speech playback is not available in this browser. Read the transcript or use your own voice.');return}let vs=suitableVoices();let v=vs.find(x=>x.voiceURI===state.voice)||vs.find(x=>x.lang===state.accent)||vs[0];if(!v){notify('No English voice is installed. You can still use all transcripts and recording exercises.');return}const utter=new SpeechSynthesisUtterance(text);utter.voice=v;utter.lang=v.lang;utter.rate=.91;utter.pitch=1;utter.volume=1;speechSynthesis.speak(utter)}
function notify(s){let el=$('#audio-message');if(el)el.textContent=s;else alert(s)}
const introSamples={a2:'Hello, my name is Véronique. I am learning English. I would like to speak more confidently with other people. I enjoy travelling and I am preparing for the LILATE.',b1:'Good morning, my name is Véronique. I am currently improving my English so that I can communicate more confidently in everyday and professional situations. I enjoy travelling, particularly planning visits and solving practical problems. I am preparing for the LILATE and I would like to express myself more naturally.'};
const phrases=[
{title:'1 · WELCOME',rule:'Greeting + your name + a useful opening question',fr:'Saluer, se présenter puis ouvrir l’échange.',ex:'Good morning. This is Véronique speaking. How can I help you today?',variants:['Good afternoon. How may I help you?','Hello, welcome. What can I do for you?']},
{title:'2 · IDENTIFY THE NEED',rule:'Use an open question (what / how / when / which) and listen for the purpose.',fr:'Identifier la personne, son besoin et le contexte.',ex:'Could you tell me what you are looking for?',variants:['May I have your name, please?','What would you like to know about the service?']},
{title:'3 · CLARIFY / REFORMULATE',rule:'Repeat the essential detail + ask for confirmation.',fr:'Reformuler l’essentiel sans traduire mot à mot.',ex:'So, you would like to change the appointment to Thursday. Is that correct?',variants:['Sorry, could you say that a little more slowly?','Just to confirm, you need two places, not three. Is that right?']},
{title:'4 · OFFER A NEXT STEP',rule:'I can + base verb, I could + base verb, Let me + base verb.',fr:'Proposer une solution concrète.',ex:'I can send the information by email this afternoon.',variants:['Let me check that for you.','Would you like me to arrange a call?']},
{title:'5 · CONFIRM AND CLOSE',rule:'Confirm the next action and close naturally.',fr:'Confirmer les éléments, remercier puis terminer poliment.',ex:'I will send you a confirmation email. Thank you for calling. Have a lovely day.',variants:['We look forward to seeing you on Friday.','Thank you. Please contact us if you need anything else.']}
];
const vocab={
'Welcoming':[['welcome','accueillir','greet or receive somebody','Welcome to our office.'],['enquiry','demande de renseignements','request for information','I am calling about an enquiry.'],['visitor','visiteur','someone who arrives to see a place or person','A visitor is waiting at reception.'],['appointment','rendez-vous','a scheduled meeting','Can we change the appointment?']],
'Understanding':[['request','demande','something someone asks for','Could you explain your request?'],['clarify','clarifier','make a point clearer','I need to clarify one detail.'],['confirm','confirmer','check a fact is correct','Could you confirm the date?'],['spell','épeler','say letters one at a time','Could you spell your surname?']],
'Helping':[['available','disponible','free or possible to use','Are you available on Thursday?'],['arrange','organiser','plan a meeting or action','I can arrange a call.'],['forward','transférer','send information to someone else','I will forward your message.'],['follow up','faire un suivi','contact again after an earlier request','I will follow up tomorrow.']],
'Polite phrases':[['Could you repeat that, please?','Pourriez-vous répéter ?','ask someone to say it again','Could you repeat the date, please?'],['Would that work for you?','Cela vous conviendrait-il ?','check whether an option is suitable','I have a slot at ten. Would that work for you?'],['Let me check.','Laissez-moi vérifier.','ask for time before confirming','Let me check the information.'],['Is that correct?','Est-ce bien cela ?','verify your understanding','You need two tickets. Is that correct?']]
};
const drillQuestions=[
{id:'q1',kind:'single',title:'Choose an appropriate welcome',prompt:'A new client calls your office. Which reply is both professional and natural?',options:['What do you want?','Good morning. How can I help you?','You speak to me now.'],correct:1,hint:'Start with a greeting, then an open offer of help.',explain:'A friendly professional opening is clear and direct. “What do you want?” sounds abrupt.'},
{id:'q2',kind:'single',title:'Check someone’s name',prompt:'You did not hear the surname. What should you say?',options:['Could you spell your surname, please?','You spell your surname.','What surname you are?'],correct:0,hint:'Could you + base verb + ... + please?',explain:'“Could you spell ...?” is a polite request, not a command.'},
{id:'q3',kind:'single',title:'Professional introduction',prompt:'You want to say your role. Which sentence is correct?',options:['I work in as an assistant.','I am work assistant.','I work as an assistant.'],correct:2,hint:'Use work as + job; work in + sector; work for + employer.',explain:'Use “work as” with job titles. Use “work in” before an area of activity.'},
{id:'q4',kind:'multi',title:'Useful ways to clarify',prompt:'Select ALL responses that politely clarify a request.',options:['Just to confirm, you need a meeting on Tuesday?','Say it faster.','Could you repeat the time, please?','So you would like us to call you tomorrow?'],correct:[0,2,3],hint:'Choose phrases that check or ask for information politely.',explain:'Paraphrasing and asking for repetition are appropriate. “Say it faster” makes understanding harder.'},
{id:'q5',kind:'fill',title:'Polite question structure',prompt:'Complete: “Could you ______ your email address, please?”',correct:['confirm','repeat','spell'],hint:'Choose a base-form verb meaning check, say again or spell.',explain:'After could, use the base form, not “to confirm” or “confirming”.'},
{id:'q6',kind:'single',title:'Offer help with can',prompt:'Choose the correct sentence.',options:['I can to send the document.','I can sending the document.','I can send the document.'],correct:2,hint:'can + base verb, never “to” or -ing immediately after can.',explain:'Can is a modal auxiliary and takes the bare infinitive.'},
{id:'q7',kind:'order',title:'Put the words in order',prompt:'Build a polite question.',tokens:['you','Could','the date,','please?','confirm'],correct:'Could you confirm the date, please?',hint:'Could + subject + base verb + object + please?',explain:'“Could you confirm the date, please?” is the standard polite pattern.'},
{id:'q8',kind:'single',title:'Indirect question',prompt:'Which indirect question has the correct word order?',options:['Could you tell me when does the meeting start?','Could you tell me when the meeting starts?','Could you tell me when starts the meeting?'],correct:1,hint:'After “Could you tell me when…”, use statement word order.',explain:'Indirect questions use subject + verb: “when the meeting starts”.'},
{id:'q9',kind:'multi',title:'Close the conversation well',prompt:'Select two professional closing sentences.',options:['Thanks. Bye forever.','I’ll send you an email this afternoon.','Thank you for your call. Have a good day.','I do not know. Goodbye.'],correct:[1,2],hint:'Confirm an action and close politely.',explain:'A professional ending includes a next step or a friendly farewell.'},
{id:'q10',kind:'fill',title:'Complete the response',prompt:'Complete: “I will ______ up with you tomorrow.”',correct:['follow'],hint:'Think of the phrasal verb meaning “contact again later”.',explain:'“Follow up” means checking back after an earlier request.'},
{id:'q11',kind:'single',title:'Handling uncertainty',prompt:'A visitor asks about something you do not know. What should you say?',options:['I do not know, go away.','I invent an answer.','Let me check that for you.'],correct:2,hint:'A good response offers a next step without inventing an answer.',explain:'“Let me check that for you” keeps the conversation professional.'},
{id:'q12',kind:'order',title:'Reformulate to confirm',prompt:'Build a sentence that verifies the request.',tokens:['you','So,','a','need','new appointment.'],correct:'So, you need a new appointment.',hint:'Start with So, then subject + verb + object.',explain:'Reformulating verifies that you understand the important point.'}
];
