let page='welcome', currentRecording=null,recChunks=[],recBlob=null,recUrl=null,recSec=0,recTicker=null,timerInterval=null,timerLeft=0,timedIndex=0,timedResponses=[];
function render(){halt();const nav=$('#nav');nav.innerHTML=sections.map(([id,n,title])=>`<button class="navbutton ${page===id?'active':''} ${state.done[id]?'done':''}" data-nav="${id}"><b>${state.done[id]?'✓':n}</b>${title}</button>`).join('');let idx=sections.findIndex(x=>x[0]===page);$('#progresslabel').textContent=`${state.visited.length} of ${sections.length} steps visited`;$('#progressbar').style.width=(state.visited.length/sections.length*100)+'%';let o={welcome:renderWelcome,sound:renderSound,language:renderLanguage,identity:renderIdentity,drills:()=>renderExercises(drillQuestions,'Guided exercises','Try, correct, and repeat. This section has 12 questions. Each answer has a hint, an explanation and a model.', 'Listening & reading →'),listening:renderListening,scenarios:renderScenarios,writing:renderWriting,rehearsal:renderRehearsal};$('#content').innerHTML=o[page]();rail();bindCurrent();window.scrollTo({top:0,behavior:'instant'});save()}
function go(id){page=id;if(!state.visited.includes(id))state.visited.push(id);render()}
function mark(){state.done[page]=true;save()}
function nextButton(label='Next step →'){let i=sections.findIndex(x=>x[0]===page);return `<div class="nextbar"><button class="outline" data-nav="${sections[Math.max(0,i-1)][0]}">← Previous</button>${i<8?`<button class="primary" data-next="${sections[i+1][0]}">${label}</button>`:''}</div>`}
function header(ey,title,desc){return `<div class="section-heading"><span class="eyebrow">${ey}</span><h1>${title}</h1><p class="introline">${desc}</p></div>`}
function renderWelcome(){return `<div class="hero"><span class="tag">PART 1 OF 4 · LILATE IA SKILLS</span><span class="tag">B1 pathway</span><p class="eyebrow">ONE REALISTIC SKILL AT A TIME</p><h1>Welcome someone.<br>Understand them.<br>Respond with confidence.</h1><p>There is no need to be perfect. Your goal today is to manage a conversation from the first greeting to the next practical step.</p><button class="primary" data-next="sound">Start with the sound check →</button></div>
<div class="card"><h2>What you will learn</h2><div class="grid3"><div class="mini"><strong>01 · Welcome</strong><p>Start a professional exchange naturally.</p></div><div class="mini"><strong>02 · Identify</strong><p>Find out who is speaking and why.</p></div><div class="mini"><strong>03 · Help</strong><p>Clarify, offer a next step and confirm.</p></div></div><p class="frblock fr">Objectif : comprendre une demande, réagir poliment et faire avancer l’échange. La réussite, c’est communiquer clairement, pas réciter un dialogue parfait.</p></div>
<div class="card"><h2>How your LILATE IA context is personalised</h2><p>Before the official assessment, the candidate setup asks for professional context such as your role, sector, company name and website. According to the LILATE help centre, this information helps the IA version generate workplace situations relevant to your work. <strong>It does not mean the test copies questions from your company website or guarantees that every question will be about your employer.</strong></p><div class="grid2"><div class="mini"><strong>What to prepare</strong><p>Your job or previous job, your sector, two everyday responsibilities, the organisation’s name and website (if relevant).</p></div><div class="mini"><strong>What if you are retired?</strong><p>Use your previous professional context. If you are changing career, describe your current or target role accurately.</p></div></div><p class="frblock fr">Dans l’espace candidat officiel, renseignez les informations professionnelles demandées : métier, secteur et entreprise, ainsi que son site Internet si le formulaire le propose. Les mises en situation peuvent être adaptées à ces informations, sans être garanties à l’identique.</p><p class="small"><a href="https://help.lilate.org/fr/article/comment-passer-mon-test-lilate-modalite-ia-10yxtas/" target="_blank" rel="noopener">Official: How to take the IA test</a> · <a href="https://help.lilate.org/fr/article/le-lilate-sadapte-t-il-a-mon-metier-personnel-kyd7nv/" target="_blank" rel="noopener">Official: Professional adaptation</a></p></div>
<div class="card"><h2>Your training route</h2><p>Start with the language you need, then practise it in short questions, calls, messages and conversations. Only the last section offers an optional countdown. You control the pace.</p><div class="mini"><strong>What this is — and is not</strong><p>This practice follows the general competency of welcoming and interacting. Its page layout, questions, timings and feedback are independent learning tools, <strong>not a reproduction of the exact LILATE interface or scoring algorithm</strong>.</p></div></div>${nextButton('Sound & confidence →')}`}
function renderSound(){return `${header('02 · AUDIO SETTINGS','Find a voice you can understand','Choose a clear English voice already available on your device. Nothing plays unless you press Listen.')}
<div class="card"><h2>Your listening settings</h2><label class="fieldlabel" for="accent">English accent</label><select class="field" id="accent"><option value="en-GB" ${state.accent==='en-GB'?'selected':''}>British English (UK)</option><option value="en-US" ${state.accent==='en-US'?'selected':''}>American English (US)</option></select><label class="fieldlabel" for="voicepick">Voice available on this computer</label><select id="voicepick" class="field"><option>Looking for voices…</option></select><div class="actions"><button class="primary" data-say="Good morning. Thank you for calling. How can I help you today?">▶ Test this voice</button><button class="outline" id="stopvoice">■ Stop audio</button><button class="outline" id="reloadvoices">Refresh voices</button></div><p class="small muted" id="audio-message">Some devices offer high-quality natural voices (for example Microsoft or Google). If only a robotic voice is installed, use the transcript without audio or choose a better voice in your computer settings.</p></div>
<div class="card"><h2>Listen for meaning — not every word</h2><p><b>Listening 1:</b> “Good morning. How can I help you today?”</p><div class="actions"><button class="outline" data-say="Good morning. How can I help you today?">▶ Listen</button><button class="outline" data-say="Good morning. How can I help you today?">↻ Hear again</button></div><p class="frblock fr">Concentrez-vous sur l'intention : la personne vous accueille et propose son aide. Vous n'avez pas besoin de traduire chaque mot.</p><p><b>Your turn:</b> Say the line in your own voice. A natural pace is better than speaking quickly.</p></div><div class="card"><h2>Microphone practice (optional)</h2><p>Record a short greeting, listen to your own voice and try again. Microphone access usually requires HTTPS or localhost. If you open this lesson directly from a file, use the text alternative.</p>${recordingHTML('sound-practice')}</div>${nextButton('Learn the language →')}`}
function renderLanguage(){return `${header('03 · LEARN BEFORE PRACTISE','The five moves of a conversation','Read each model, listen if you like, and learn why each structure works.')}${phrases.map(p=>`<div class="card"><span class="tag">${p.title}</span><h2>${escapeHTML(p.rule)}</h2><p class="frblock fr">${p.fr}</p><div class="script">${escapeHTML(p.ex)}</div><div class="actions"><button class="outline" data-say="${escapeHTML(p.ex)}">▶ Listen</button><button class="outline" data-say="${escapeHTML(p.variants[0])}">▶ Alternative phrase</button></div><details><summary>Two more expressions + examples</summary>${p.variants.map(x=>`<p class="sectionline">${escapeHTML(x)}</p>`).join('')}</details></div>`).join('')}
<div class="card"><h2>Grammar: form, use and common mistakes</h2><div class="grid2"><div class="mini"><strong>work as / in / for</strong><p><b>as</b> + profession: I work as an assistant.<br><b>in</b> + field: I work in tourism.<br><b>for</b> + employer: I work for a company.<br><b>Past:</b> I used to work in administration.<br><b>Negative:</b> I don't work in sales.<br><b>Question:</b> Do you work with clients?</p></div><div class="mini"><strong>Could + subject + base verb?</strong><p><b>Affirmative:</b> I can help.<br><b>Negative:</b> I can't confirm yet.<br><b>Question:</b> Could you repeat that, please?<br><b>Indirect:</b> Could you tell me when the meeting starts?<br><b>Avoid:</b> “Could you to repeat?”</p></div><div class="mini"><strong>Present simple vs continuous</strong><p><b>Routine:</b> I usually answer enquiries.<br><b>Now:</b> I am checking your appointment.<br><b>Negative:</b> I don't have the answer yet.<br><b>Question:</b> Are you calling about a booking?</p></div><div class="mini"><strong>Next steps</strong><p><b>I can + verb:</b> I can email you.<br><b>I'll + verb:</b> I'll check.<br><b>Would you like me to + verb?</b><br><b>Don't invent an answer:</b> I'm not sure, but I'll find out.</p></div></div><p class="frblock fr">Attention : après <b>can / could / will</b>, pas de <b>to</b> devant le verbe. Dans une question indirecte, gardez l’ordre sujet-verbe : « when the meeting starts », pas « when does the meeting start ».</p></div>
<div class="card"><h2>Vocabulary by category</h2><label class="fieldlabel" for="vocabcat">Choose a topic</label><select class="field" id="vocabcat">${Object.keys(vocab).map(k=>`<option>${k}</option>`).join('')}</select><div id="vocabitems"></div></div>${nextButton('Build your introduction →')}`}
function renderIdentity(){const p=state.profile;return `${header('04 · YOUR PROFESSIONAL PROFILE','Your introduction, your words','A simple, accurate introduction helps you respond confidently to early questions. You can talk about a current job, a previous job, or your career goal.')}
<div class="card"><h2>Build your own introduction</h2><div class="grid2"><label><span class="fieldlabel">Context</span><select id="p-context" class="field"><option value="current" ${p.context==='current'?'selected':''}>My current job</option><option value="past" ${p.context==='past'?'selected':''}>My previous job</option><option value="target" ${p.context==='target'?'selected':''}>My future professional goal</option></select></label><label><span class="fieldlabel">Job title</span><input class="field" id="p-role" value="${escapeHTML(p.role)}" placeholder="e.g. an administrative assistant"></label><label><span class="fieldlabel">Sector</span><input class="field" id="p-sector" value="${escapeHTML(p.sector)}" placeholder="e.g. education, tourism"></label><label><span class="fieldlabel">Employer (optional)</span><input class="field" id="p-company" value="${escapeHTML(p.company)}" placeholder="e.g. a local business"></label><label><span class="fieldlabel">A main responsibility (verb + object)</span><input class="field" id="p-duty" value="${escapeHTML(p.duty)}" placeholder="e.g. answer customer enquiries"></label><label><span class="fieldlabel">Another responsibility (optional)</span><input class="field" id="p-other" value="${escapeHTML(p.other)}" placeholder="e.g. organise appointments"></label></div><div class="actions"><button class="primary" id="buildintro">Build my introduction</button><button class="outline" id="copyintro">Copy introduction</button></div><div id="builtintro" class="model"></div><p class="frblock fr">Pour votre vrai parcours, utilisez des informations exactes. Les exemples ci-dessous ne sont pas des faits supposés sur votre vie professionnelle.</p></div>
<div class="card"><h2>Two level-appropriate models</h2>${modelPair(introSamples.a2,introSamples.b1,'Personal introduction models')}<div class="actions"><button class="outline" data-say="${escapeHTML(introSamples.a2)}">▶ Listen to A2+</button><button class="outline" data-say="${escapeHTML(introSamples.b1)}">▶ Listen to B1</button></div></div>
<div class="task"><span class="tasknum">SPEAKING · 01</span><h2>Introduce yourself naturally</h2><p>Speak for 30–60 seconds. Use: name → professional context → one responsibility → why English matters.</p>${recordingHTML('intro')}<label class="fieldlabel">Your speaking notes (optional)</label><textarea id="intro-notes" class="field" placeholder="Start with: My name is Véronique…"></textarea><div class="actions"><button class="outline" data-hint="Try four short sentences: My name is… / I work as… OR I used to work as… / I usually… / I’m improving my English because…">Hint</button><button class="outline" data-model="${escapeHTML(introSamples.a2)}">A2+ answer</button><button class="outline" data-model="${escapeHTML(introSamples.b1)}">B1 answer</button></div><div class="feedback" id="intro-feedback">This is a speaking rehearsal. Listen back and compare your answer with a model; the page does not pretend to automatically grade spoken accuracy.</div></div>${nextButton('Short guided exercises →')}`}
function makeTask(q,i){const s=state.answers[q.id]||{},chosen=s.selection;let choices='';if(q.kind==='single'||q.kind==='multi'){choices=`<div class="answerrow" role="group" aria-label="Answer choices">${q.options.map((opt,n)=>`<button class="choice ${q.kind==='multi'?(Array.isArray(chosen)&&chosen.includes(n)?'selected':''):(chosen===n?'selected':'')}" data-choice="${q.id}" data-idx="${n}" aria-pressed="${q.kind==='multi'?Boolean(Array.isArray(chosen)&&chosen.includes(n)):chosen===n}">${escapeHTML(opt)}</button>`).join('')}</div>`}
if(q.kind==='fill')choices=`<label class="fieldlabel" for="field-${q.id}">Type one word</label><input class="field" id="field-${q.id}" data-fill="${q.id}" value="${escapeHTML(chosen||'')}" placeholder="Type here…" autocomplete="off">`;
if(q.kind==='order')choices=`<p class="small">Click a word to add it. Click an added word to return it.</p><div class="orderarea" id="order-${q.id}">${(s.sequence||[]).map((x,k)=>`<button class="tile selected" data-tile-back="${q.id}" data-pos="${k}">${escapeHTML(x)}</button>`).join('') || '<span class="small muted">Build your sentence here…</span>'}</div><div class="answerrow" style="margin-top:9px">${shuffleDeterministic(q.tokens,q.id).filter(x=>!((s.sequence||[]).includes(x))).map(x=>`<button class="tile" data-tile="${q.id}" data-token="${escapeHTML(x)}">${escapeHTML(x)}</button>`).join('')}</div>`;
return `<article class="task" id="task-${q.id}"><div class="tasktop"><span class="tasknum">TASK ${String(i+1).padStart(2,'0')}</span><span class="tasktype">${q.kind==='multi'?'Choose several':q.kind==='single'?'Choose one':q.kind==='fill'?'Fill the gap':'Word order'}</span></div><h2>${q.title}</h2><p class="prompt">${escapeHTML(q.prompt)}</p><div class="instruction">${q.kind==='multi'?'Select all correct responses and check.':q.kind==='order'?'Build the sentence from the tiles.':'Try your answer and get instant feedback.'}</div>${choices}<div class="actions"><button class="primary" data-check="${q.id}">Check answer</button><button class="outline" data-hint="${escapeHTML(q.hint)}">Hint</button><button class="outline" data-answer="${q.id}">Show answer</button><button class="outline" data-reset="${q.id}">Try again</button></div><div class="feedback ${s.ok?'good':''}" id="fb-${q.id}">${s.feedback||'Choose or type an answer, then check.'}</div></article>`}
function shuffleDeterministic(arr,id){let v=[...arr],seed=[...id].reduce((a,c)=>a+c.charCodeAt(0),0)*37;for(let j=v.length-1;j>0;j--){let k=(seed+j*31)%(j+1);[v[j],v[k]]=[v[k],v[j]]}return v}
function renderExercises(q,title,desc,label){return `${header('05 · GUIDED EXERCISES',title,desc)}<div class="card"><h2>How feedback works</h2><p>Every question has a hint, a model answer, and an explanation. If your answer is not correct, you can revise it immediately. Your score is not used for certification.</p><p class="frblock fr">Le but est d’apprendre. Vous avez le droit de vous tromper et de recommencer. Les mots dans les propositions ne sont pas toujours dans le même ordre.</p></div>${q.map(makeTask).join('')}${nextButton(label)}`}
function renderListening(){return `${header('06 · UNDERSTAND THE REQUEST','Listening, reading and key details','You are not trying to understand every word. Listen for WHO, WHAT, WHEN and the NEXT ACTION.')}
<div class="card"><h2>Listening technique</h2><div class="grid2"><div class="mini"><strong>First listen</strong><p>What is the general situation? Who needs help?</p></div><div class="mini"><strong>Second listen</strong><p>Capture the day, time, name, number or action.</p></div></div><p class="frblock fr">Ne traduisez pas tout. Repérez QUI / QUOI / QUAND / DEMANDE / PROCHAINE ACTION. Le texte est disponible si vous en avez besoin.</p></div>
${listeningItems.map((item,i)=>`<article class="task"><span class="tasknum">LISTENING ${i+1} OF ${listeningItems.length}</span><h2>${item.title}</h2><p>Listen to this original example and then answer the question.</p><div class="actions"><button class="primary" data-say="${escapeHTML(item.text)}">▶ Listen</button><button class="outline" data-say="${escapeHTML(item.text)}">↻ Listen again</button><button class="outline" data-transcript="${item.id}">Show / hide transcript</button></div><div class="script ${state.showTranscript[item.id]?'':'hide'}" id="trans-${item.id}">${escapeHTML(item.text)}</div>${makeTask({...item,kind:'single',prompt:item.question},i)}</article>`).join('')}
<div class="card"><h2>Short reading tasks</h2><p>Read the request and identify the essential information before responding.</p></div>${readingItems.map((q,i)=>makeTask(q,i)).join('')}${nextButton('Professional interactions →')}`}
function recordingHTML(id){return `<div class="actions"><button class="recbtn" data-rec="${id}">● Start recording</button><button class="recbtn" data-stoprec="${id}" disabled>■ Stop</button><button class="recbtn" data-playrec="${id}" disabled>▶ Play my recording</button></div><p class="small muted" id="rec-status-${id}">Your recording stays on this device and is not sent to a server. You may also speak without recording.</p><audio controls id="rec-audio-${id}" class="hide"></audio>`}
function modelPair(a2,b1,title){return `<div class="modelrow"><div class="speaking"><span class="tag">A2+ · CLEAR & SHORT</span><p>${escapeHTML(a2)}</p></div><div class="speaking"><span class="tag">B1 · MORE DEVELOPED</span><p>${escapeHTML(b1)}</p></div></div>`}
function renderScenarios(){return `${header('07 · PROFESSIONAL DIALOGUES','Practise complete conversations','These are original workplace examples, not recalled test questions. Choose one situation, listen to the dialogue, then produce your own response.')}
<div class="card"><h2>The five-step strategy</h2><div class="grid3"><div class="mini"><strong>Welcome</strong><p>Friendly greeting</p></div><div class="mini"><strong>Identify</strong><p>Name and purpose</p></div><div class="mini"><strong>Clarify</strong><p>Repeat the essential information</p></div><div class="mini"><strong>Respond</strong><p>Offer a realistic next action</p></div><div class="mini"><strong>Confirm</strong><p>Check the plan</p></div></div></div>
${scenarioData.map((s,i)=>`<div class="card"><span class="tag">SCENARIO ${i+1}</span><h2>${s.name}</h2><p><b>Situation:</b> ${s.context}</p><p class="small"><b>Mission:</b> ${s.goal}</p><div class="actions"><button class="outline" data-say="${escapeHTML(s.dialogue.map(d=>d[1]).join(' '))}">▶ Hear example dialogue</button></div><details><summary>Read complete dialogue / transcript</summary><div class="script">${s.dialogue.map(d=>`<p><span class="speaker">${d[0]}:</span> ${d[1]}</p>`).join('')}</div></details><div class="task"><span class="tasknum">YOUR RESPONSE · SPEAK OR WRITE</span><p class="prompt">${s.prompt}</p><div class="instruction">Follow the five moves. You can write a response, speak it out loud, or record it.</div><textarea class="field" id="scenario-${s.id}" data-scenariotext="${s.id}" rows="4" placeholder="Good morning…">${escapeHTML((state.answers[s.id]||{}).text||'')}</textarea>${recordingHTML(s.id)}<div class="actions"><button class="primary" data-scheck="${s.id}">Check my key points</button><button class="outline" data-shint="${s.id}">Step-by-step hint</button><button class="outline" data-smodel="${s.id}" data-level="a2">A2+ model</button><button class="outline" data-smodel="${s.id}" data-level="b1">B1 model</button></div><div class="feedback" id="sf-${s.id}">A personal answer can have several correct forms. The keyword check gives guidance, not an official grade.</div></div></div>`).join('')}${nextButton('Writing & speaking tasks →')}`}
const writingTasks=[{id:'write1',name:'Welcome email',context:'A new client asks how to arrange an introductory call next week. Write 3–5 sentences. Welcome them, ask which day suits them, offer to check availability and close politely.',a2:'Hello, thank you for your message. When are you available next week? I can check our appointments. Kind regards, Véronique.',b1:'Dear Ms Evans, thank you for your enquiry. I would be happy to help you arrange an introductory call. Could you let me know which day and time would suit you next week? I can check availability and send you a confirmation. Kind regards, Véronique.',keys:['thank','available','check']},{id:'write2',name:'A clear appointment confirmation',context:'A visitor wants to change a meeting to Thursday at 11:00. Write a short confirmation or explain that you need to check first. Do not invent availability.',a2:'Hello, you would like Thursday at eleven. I will check if this time is available and confirm soon. Thank you.',b1:'Hello, thank you for your message. Just to confirm, you would like to move the meeting to Thursday at 11 a.m. I will check whether that time is available and get back to you as soon as I can. Kind regards, Véronique.',keys:['thursday','11','check']},{id:'write3',name:'A professional follow-up',context:'You could not answer a price question during a call. Write to the customer to acknowledge the enquiry, explain that you are checking and offer a follow-up.',a2:'Hello, thank you for your call. I will check the price and email you soon. Kind regards, Véronique.',b1:'Dear Mr Lee, thank you for your call earlier today. I understand that you would like more information about the price of the personalised service. I am checking the details with my colleague and will follow up by email. Best regards, Véronique.',keys:['thank','price','check']}];
function renderWriting(){return `${header('08 · EXPRESS YOURSELF','Writing and speaking with a clear structure','A good short response is more useful than a long, complicated response. Use the purpose → detail → action → closing pattern.')}
<div class="card"><h2>A simple reply framework</h2><div class="grid2"><div class="mini"><strong>Step 1 · Thank or welcome</strong><p>Thank you for your message.</p></div><div class="mini"><strong>Step 2 · Reformulate the need</strong><p>I understand that you would like to change the meeting.</p></div><div class="mini"><strong>Step 3 · Give a next step</strong><p>I'll check availability and get back to you.</p></div><div class="mini"><strong>Step 4 · Close professionally</strong><p>Kind regards, Véronique.</p></div></div><p class="frblock fr">Méthode : remercier → reformuler → annoncer l’action → conclure. N'affirmez pas qu'un rendez-vous est confirmé si vous n'avez pas vérifié.</p></div>
${writingTasks.map((t,i)=>`<article class="task"><span class="tasknum">WRITING ${i+1}</span><h2>${t.name}</h2><p>${t.context}</p><textarea class="field" id="${t.id}" rows="5" placeholder="Write your message here…">${escapeHTML((state.answers[t.id]||{}).text||'')}</textarea><div class="actions"><button class="primary" data-wcheck="${t.id}">Check key elements</button><button class="outline" data-whint="${t.id}">Hint</button><button class="outline" data-wmodel="${t.id}" data-level="a2">A2+ model</button><button class="outline" data-wmodel="${t.id}" data-level="b1">B1 model</button></div><div class="feedback" id="wf-${t.id}">Write your response, then check its key elements. Multiple correct answers are possible.</div></article>`).join('')}
<div class="task"><span class="tasknum">SPEAKING · FINAL</span><h2>Your own welcome conversation</h2><p>A client says: “Hello, I would like to make an appointment, but I’m not sure who I need to speak to.” Respond for 45–60 seconds. Welcome, clarify, offer a next step and confirm.</p>${recordingHTML('final-speaking')}<div class="actions"><button class="outline" data-hint="Welcome → Could you tell me a little more about the purpose of your appointment? → I'll check who can help. → May I have your name and contact details?">Hint</button><button class="outline" data-model="Hello, thank you for calling. What is the appointment about? I will check who can help you. May I have your name, please?">A2+ model</button><button class="outline" data-model="Good morning and thank you for contacting us. I'd be happy to help. Could you tell me a little more about the reason for your appointment? That will help me direct you to the right person. I can check their availability and get back to you. May I have your name and preferred contact details, please?">B1 model</button></div><div class="feedback">Listen to your recording, compare it with the models, and try again. Speech scoring is not automated.</div></div>${nextButton('Optional practice simulation →')}`}
const timedQs=[{prompt:'A new caller says: “I would like to speak with someone about your services.” Choose the best first response.',options:['What services?','Good morning. Could you tell me which service you are interested in?','I have no time.'],correct:1},{prompt:'A visitor asks: “Can you tell me when the appointment starts?” Choose the best clarification.',options:['Could you tell me which appointment you mean?','You should know.','There are no appointments.'],correct:0},{prompt:'You cannot confirm an available time yet. Choose the professional next step.',options:['It is certainly free.','I will invent a time.','Let me check availability and get back to you.'],correct:2},{prompt:'The visitor says “There will be three people instead of four.” What changed?',options:['The address','The number of visitors','The time'],correct:1},{prompt:'A caller asks you to repeat a name. Which phrase is correct?',options:['Could you spell that for me, please?','Could you spelling that for me?','You spell it now.'],correct:0}];
function renderRehearsal(){return `${header('09 · OPTIONAL PRACTICE','You are ready for a short simulation','This is an independent five-question practice round, not a replica of LILATE timing or scoring. There is no requirement to complete it.')}
<div class="card"><h2>Choose your level of support</h2><p>You already practised welcoming, understanding, clarifying and offering a next step. Here, you can try five new questions with a short timer, then review your answers and explanations.</p><div id="timedarea"><p class="frblock fr">Le chronomètre est facultatif. Si vous préférez travailler sans minuterie, reprenez les exercices guidés. Ce résultat n'est pas une note LILATE.</p><button class="primary" id="starttimed">Start five-question rehearsal →</button></div></div><div class="card"><h2>Your reflection</h2><p>What do you already do confidently? What would you like to practise next time?</p><textarea class="field" id="reflection" placeholder="For example: I can greet a caller, but I want to practise asking questions.">${escapeHTML(state.notes)}</textarea><div class="actions"><button class="outline" id="exportnotes">Download my notes</button><button class="outline" id="resetprogress">Reset lesson progress</button></div></div>${nextButton()}`}
function rail(){const data={welcome:['Your objective',['Understand the competency','Read the official-personalisation guidance','Start without a timer']],sound:['Sound settings',['Choose UK or US','Select a voice','Listen only when ready','Record your own short greeting']],language:['Your language toolkit',['Welcome','Ask questions','Clarify','Offer help','Confirm']],identity:['Your real introduction',['Choose current / previous / future role','Build four short sentences','Practise aloud']],drills:['Short practice',['Choose an option','Use Hint if needed','Check and correct','Review the model']],listening:['Listen efficiently',['Situation first','Key details second','Transcript when needed','Then answer']],scenarios:['Act professionally',['Welcome','Identify the request','Clarify','Offer a next step','Confirm']],writing:['Express your idea',['Thank the person','Restate the need','Give a realistic next step','Close politely']],rehearsal:['Optional simulation',['Five original questions','Short, optional timers','Final review','No official score']]};let [title,list]=data[page];$('#railtitle').textContent=title;$('#railcontent').innerHTML=`<ul>${list.map(x=>`<li>${x}</li>`).join('')}</ul><p class="frblock fr">N'avancez que lorsque vous vous sentez à l'aise.</p>`}
function renderVocabulary(){let cat=$('#vocabcat')?.value||Object.keys(vocab)[0],root=$('#vocabitems');if(!root)return;root.innerHTML=vocab[cat].map(v=>`<div class="mini" style="margin-top:10px"><strong>${v[0]} <button class="outline" style="padding:2px 8px;font-size:11px;float:right" data-say="${escapeHTML(v[0])}">▶ Listen</button></strong><span class="frhelp fr">${v[1]}</span><p><b>Definition:</b> ${v[2]}</p><p><b>Example:</b> ${v[3]}</p></div>`).join('')}
function updateVoiceList(){const el=$('#voicepick');if(!el)return;let vs=suitableVoices().filter(v=>v.lang===state.accent);if(!vs.length)vs=suitableVoices();el.innerHTML=vs.length?vs.map(v=>`<option value="${escapeHTML(v.voiceURI)}" ${state.voice===v.voiceURI?'selected':''}>${escapeHTML(v.name)} (${escapeHTML(v.lang)})${/natural|neural|premium|enhanced/i.test(v.name)?' · enhanced':''}</option>`).join(''):'<option value="">No installed English voices detected</option>';if(vs.length&&!vs.some(v=>v.voiceURI===state.voice)){state.voice=vs[0].voiceURI;el.value=state.voice}save()}
function buildIntroduction(){let p=state.profile, role=p.role.trim()||'[your job title]',sector=p.sector.trim(),company=p.company.trim(),duty=p.duty.trim()||'[a responsibility]',other=p.other.trim();let start=p.context==='past'?`I used to work as ${role}`:p.context==='target'?`I am preparing to work as ${role}`:`I work as ${role}`;let st=`Hello, my name is Véronique. ${start}${sector?' in '+sector:''}${company?' for '+company:''}. ${p.context==='past'?'My responsibilities included':'My responsibilities include'} ${duty}${other?' and '+other:''}. I am improving my English so that I can communicate more confidently.`;let el=$('#builtintro');if(el)el.textContent=st;return st}
function bindCurrent(){if(page==='sound'){updateVoiceList();const acc=$('#accent');if(acc)acc.addEventListener('change',e=>{state.accent=e.target.value;state.voice='';updateVoiceList()});$('#voicepick')?.addEventListener('change',e=>{state.voice=e.target.value;save()});$('#reloadvoices')?.addEventListener('click',updateVoiceList);$('#stopvoice')?.addEventListener('click',halt)}if(page==='language'){$('#vocabcat')?.addEventListener('change',renderVocabulary);renderVocabulary()}
if(page==='identity'){['context','role','sector','company','duty','other'].forEach(k=>$('#p-'+k)?.addEventListener('input',e=>{state.profile[k]=e.target.value;buildIntroduction();save()}));buildIntroduction();$('#buildintro')?.addEventListener('click',buildIntroduction);$('#copyintro')?.addEventListener('click',()=>navigator.clipboard?.writeText(buildIntroduction()).then(()=>notify('Copied.')))}if(page==='rehearsal'){$('#reflection')?.addEventListener('input',e=>{state.notes=e.target.value;save()});$('#starttimed')?.addEventListener('click',startTimed);$('#exportnotes')?.addEventListener('click',exportNotes);$('#resetprogress')?.addEventListener('click',()=>{if(confirm('Reset progress and practice answers?')){state.visited=['welcome'];state.answers={};state.done={};save();go('welcome')}})} }
function normalized(x){return String(x||'').trim().toLowerCase().replace(/[’]/g,"'").replace(/[.,!?;:]/g,'').replace(/\s+/g,' ')}
function answerText(q){if(q.kind==='single')return q.options[q.correct];if(q.kind==='multi')return q.correct.map(i=>q.options[i]).join(' / ');if(q.kind==='fill')return q.correct[0];return q.correct}
function checkAnswer(id){let q=[...drillQuestions,...readingItems,...listeningItems.map(i=>({...i,kind:'single',prompt:i.question}))].find(x=>x.id===id);if(!q)return;const s=state.answers[id]||{};if(q.kind==='fill'){s.selection=$('#field-'+id)?.value.trim()||''}let valid=false;if(q.kind==='single')valid=s.selection===q.correct;if(q.kind==='multi')valid=Array.isArray(s.selection)&&JSON.stringify([...s.selection].sort())===JSON.stringify([...q.correct].sort());if(q.kind==='fill')valid=q.correct.some(x=>normalized(x)===normalized(s.selection));if(q.kind==='order')valid=normalized((s.sequence||[]).join(' '))===normalized(q.correct);s.ok=valid;s.feedback=(valid?'✓ Correct. ':'Not quite yet. ')+q.explain;state.answers[id]=s;save();const f=$('#fb-'+id);if(f){f.className='feedback '+(valid?'good':'try');f.textContent=s.feedback}if(valid)mark()}
function selectChoice(id,idx){let q=[...drillQuestions,...readingItems,...listeningItems.map(i=>({...i,kind:'single'}))].find(x=>x.id===id);if(!q)return;let s=state.answers[id]||{};if(q.kind==='multi'){let arr=Array.isArray(s.selection)?[...s.selection]:[];s.selection=arr.includes(idx)?arr.filter(i=>i!==idx):[...arr,idx]}else s.selection=idx;state.answers[id]=s;save();let el=$('#task-'+id);if(el)el.querySelectorAll('.choice').forEach(b=>{let i=Number(b.dataset.idx),sel=q.kind==='multi'?s.selection.includes(i):s.selection===i;b.classList.toggle('selected',sel);b.setAttribute('aria-pressed',sel)})}
function showAnswer(id){let q=[...drillQuestions,...readingItems,...listeningItems.map(i=>({...i,kind:'single'}))].find(x=>x.id===id);if(!q)return;let el=$('#fb-'+id);if(el){el.className='feedback good';el.innerHTML=`<strong>Model answer:</strong> ${escapeHTML(answerText(q))}<p>${escapeHTML(q.explain)}</p>`}}
function resetQuestion(id){delete state.answers[id];save();const q=[...drillQuestions,...readingItems,...listeningItems.map(i=>({...i,kind:'single',prompt:i.question}))].find(x=>x.id===id);if(q){const target=$('#task-'+id);if(target)target.outerHTML=makeTask(q,0)}}
function keyFeedback(text,keys){let words=normalized(text);let found=keys.filter(k=>words.includes(k)),miss=keys.filter(k=>!words.includes(k));return {found,miss,html:`${found.length?`✓ You included: <b>${found.join(', ')}</b>. `:''}${miss.length?`Ideas to add or express differently: <b>${miss.join(', ')}</b>. `:'You covered the main points. ' }This is a coaching check for key ideas, not an assessment of all possible correct English.`}}
function handleScenario(id){const s=scenarioData.find(x=>x.id===id);let text=$('#scenario-'+id)?.value||'',fb=$('#sf-'+id);state.answers[id]={...(state.answers[id]||{}),text};save();if(!text.trim()){fb.textContent='Start with one friendly sentence, then add the next step.';return}fb.innerHTML=keyFeedback(text,s.check).html+'<p>Read your response aloud and compare it with a model.</p>';if(s.check.every(k=>normalized(text).includes(k)))mark()}
function handleWriting(id){const t=writingTasks.find(x=>x.id===id);let text=$('#'+id)?.value||'',fb=$('#wf-'+id);state.answers[id]={...(state.answers[id]||{}),text};save();if(!text.trim()){fb.textContent='Write a few sentences first. You can use the hint and models.';return}fb.innerHTML=keyFeedback(text,t.keys).html;if(t.keys.every(k=>normalized(text).includes(k)))mark()}
function addRecordingEvent(id){/* recording handled by delegated button events */}
async function startRecording(id){if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){notify('Microphone recording requires a supported browser and HTTPS or localhost. You can still practise aloud and type notes.');return}try{if(currentRecording&&currentRecording.state==='recording')currentRecording.stop();const stream=await navigator.mediaDevices.getUserMedia({audio:true});recChunks=[];recBlob=null;let opts=MediaRecorder.isTypeSupported('audio/webm')?{mimeType:'audio/webm'}:{};currentRecording=new MediaRecorder(stream,opts);currentRecording.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data)};currentRecording.onstop=()=>{recBlob=new Blob(recChunks,{type:currentRecording.mimeType||'audio/webm'});if(recUrl)URL.revokeObjectURL(recUrl);recUrl=URL.createObjectURL(recBlob);let audio=$('#rec-audio-'+id);if(audio){audio.src=recUrl;audio.classList.remove('hide')}const play=document.querySelector(`[data-playrec="${id}"]`);if(play)play.disabled=false;const status=$('#rec-status-'+id);if(status)status.textContent='Recording ready. Listen and try again if you want.';stream.getTracks().forEach(t=>t.stop())};currentRecording.start();let start=document.querySelector(`[data-rec="${id}"]`),stop=document.querySelector(`[data-stoprec="${id}"]`);if(start){start.textContent='● Recording…';start.classList.add('recording')}if(stop)stop.disabled=false;let st=$('#rec-status-'+id);if(st)st.textContent='Recording now. Speak naturally, then press Stop.'}catch(err){notify('Microphone unavailable or permission declined. You can still speak without recording and use the written models.')}}
function stopRecording(id){if(currentRecording&&currentRecording.state==='recording')currentRecording.stop();let b=document.querySelector(`[data-rec="${id}"]`),s=document.querySelector(`[data-stoprec="${id}"]`);if(b){b.textContent='● Record again';b.classList.remove('recording')}if(s)s.disabled=true}
function playRecording(id){let a=$('#rec-audio-'+id);if(a?.src)a.play().catch(()=>notify('Playback unavailable. Please check your browser audio settings.'))}
function startTimed(){halt();timedIndex=0;timedResponses=[];timedQuestion()}
function timedQuestion(){clearInterval(timerInterval);let area=$('#timedarea');if(!area)return;if(timedIndex>=timedQs.length){let count=timedResponses.reduce((a,x,i)=>a+(x===timedQs[i].correct?1:0),0);area.innerHTML=`<h3>Practice completed</h3><p class="endmsg">${count} of ${timedQs.length} training questions correct.</p><p>This is not an official LILATE result. Review the answers below and try again when you wish.</p>${timedQs.map((q,i)=>`<div class="mini" style="margin:10px 0"><b>Question ${i+1}</b><p>${escapeHTML(q.prompt)}</p><p>${timedResponses[i]===q.correct?'✓ Correct':'Review'} · Model: ${escapeHTML(q.options[q.correct])}</p></div>`).join('')}<button class="primary" id="replaytimed">Try again</button>`;$('#replaytimed').addEventListener('click',startTimed);mark();return}let q=timedQs[timedIndex];timerLeft=35;area.innerHTML=`<div class="tasktop"><span class="tasknum">QUESTION ${timedIndex+1} / ${timedQs.length}</span><span class="timer" id="timer">00:35</span></div><div class="meter"><span id="timerbar" style="width:100%"></span></div><p class="prompt">${escapeHTML(q.prompt)}</p><div class="answerrow">${q.options.map((x,i)=>`<button class="choice" data-timedopt="${i}">${escapeHTML(x)}</button>`).join('')}</div><p class="small muted">Choose one answer. This rehearsal automatically advances if time expires.</p><div class="actions"><button class="primary" id="timednext">Confirm and continue →</button><button class="outline" id="timedexit">Leave simulation</button></div>`;let chosen=null;area.querySelectorAll('[data-timedopt]').forEach(btn=>btn.addEventListener('click',()=>{chosen=Number(btn.dataset.timedopt);area.querySelectorAll('[data-timedopt]').forEach(x=>x.classList.toggle('selected',x===btn))}));const proceed=()=>{clearInterval(timerInterval);timedResponses.push(chosen);timedIndex++;timedQuestion()};$('#timednext').addEventListener('click',proceed);$('#timedexit').addEventListener('click',()=>{clearInterval(timerInterval);render()});timerInterval=setInterval(()=>{timerLeft--;let display=$('#timer'),bar=$('#timerbar');if(display)display.textContent=`00:${String(Math.max(0,timerLeft)).padStart(2,'0')}`;if(bar)bar.style.width=Math.max(0,timerLeft)/35*100+'%';if(timerLeft<=0)proceed()},1000)}
function exportNotes(){const txt=`Véronique — LILATE IA Part 1 | Personal practice notes\n\nProgress: ${state.visited.length} of ${sections.length} sections visited\n\nIntroduction:\n${buildIntroduction()}\n\nReflection:\n${state.notes}\n\nUseful phrases:\n${phrases.map(x=>x.ex).join('\n')}\n\nOfficial help: https://help.lilate.org/\n`;const blob=new Blob([txt],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Veronique_LILATE_Part_1_Notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function info(){const dlg=$('#disclaimer');if(!dlg.open)dlg.showModal()}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.nav){clearInterval(timerInterval);go(d.nav);return}if(d.next){mark();go(d.next);return}if(d.say){speak(d.say);return}if(d.choice){selectChoice(d.choice,Number(d.idx));return}if(d.check){checkAnswer(d.check);return}if(d.hint){const f=el.closest('.task')?.querySelector('.feedback');if(f){f.className='feedback';f.textContent='Hint: '+d.hint}else alert(d.hint);return}if(d.answer){showAnswer(d.answer);return}if(d.reset){resetQuestion(d.reset);return}if(d.tile){const s=state.answers[d.tile]||{};s.sequence=[...(s.sequence||[]),d.token];state.answers[d.tile]=s;save();const q=drillQuestions.find(q=>q.id===d.tile)||readingItems.find(q=>q.id===d.tile);if(q){$('#task-'+d.tile).outerHTML=makeTask(q,0)}return}if(d.tileBack){const s=state.answers[d.tileBack]||{};s.sequence=(s.sequence||[]).filter((_,i)=>i!==Number(d.pos));state.answers[d.tileBack]=s;save();const q=drillQuestions.find(q=>q.id===d.tileBack)||readingItems.find(q=>q.id===d.tileBack);if(q){$('#task-'+d.tileBack).outerHTML=makeTask(q,0)}return}if(d.transcript){state.showTranscript[d.transcript]=!state.showTranscript[d.transcript];$('#trans-'+d.transcript)?.classList.toggle('hide',!state.showTranscript[d.transcript]);save();return}if(d.rec){startRecording(d.rec);return}if(d.stoprec){stopRecording(d.stoprec);return}if(d.playrec){playRecording(d.playrec);return}if(d.scheck){handleScenario(d.scheck);return}if(d.shint){let s=scenarioData.find(x=>x.id===d.shint),f=$('#sf-'+d.shint);f.innerHTML=`<b>Build it step by step:</b><ol>${s.hints.map(h=>`<li>${escapeHTML(h)}</li>`).join('')}</ol>`;return}if(d.smodel){let s=scenarioData.find(x=>x.id===d.smodel),f=$('#sf-'+d.smodel);f.innerHTML=`<b>${d.level.toUpperCase()} model answer:</b><div class="model">${escapeHTML(s[d.level])}</div><button class="outline" data-say="${escapeHTML(s[d.level])}">▶ Listen to model</button>`;return}if(d.wcheck){handleWriting(d.wcheck);return}if(d.whint){let t=writingTasks.find(x=>x.id===d.whint),f=$('#wf-'+d.whint);f.textContent='Hint: Begin by thanking the person; restate their request; promise a realistic next step; close politely.';return}if(d.wmodel){let t=writingTasks.find(x=>x.id===d.wmodel),f=$('#wf-'+d.wmodel);f.innerHTML=`<b>${d.level.toUpperCase()} model:</b><div class="model">${escapeHTML(t[d.level])}</div>`;return}if(d.model){let f=el.closest('.task')?.querySelector('.feedback');if(f){f.innerHTML=`<b>Example:</b><div class="model">${escapeHTML(d.model)}</div>`}return}});
document.addEventListener('input',e=>{if(e.target.dataset.fill){let id=e.target.dataset.fill;state.answers[id]={...(state.answers[id]||{}),selection:e.target.value};save()}if(e.target.dataset.scenariotext){let id=e.target.dataset.scenariotext;state.answers[id]={...(state.answers[id]||{}),text:e.target.value};save()}if(e.target.id?.startsWith('write')){let id=e.target.id;state.answers[id]={...(state.answers[id]||{}),text:e.target.value};save()}});
$('#frbtn').addEventListener('click',()=>{state.fr=!state.fr;document.body.classList.toggle('hide-fr',!state.fr);$('#frbtn').textContent='FR help: '+(state.fr?'ON':'OFF');$('#frbtn').setAttribute('aria-pressed',String(state.fr));save()});$('#aboutbtn').addEventListener('click',info);$('#printbtn').addEventListener('click',()=>window.print());$('#enter').addEventListener('click',()=>$('#disclaimer').close());
const originalStyle=document.createElement('style');originalStyle.textContent='.hide-fr .fr{display:none!important}';document.head.appendChild(originalStyle);document.body.classList.toggle('hide-fr',!state.fr);$('#frbtn').textContent='FR help: '+(state.fr?'ON':'OFF');go('welcome');if(!sessionStorage.getItem('veronique-lilate-v2-accepted')){$('#disclaimer').showModal();$('#enter').addEventListener('click',()=>sessionStorage.setItem('veronique-lilate-v2-accepted','yes'),{once:true})}if('speechSynthesis' in window){speechSynthesis.addEventListener?.('voiceschanged',updateVoiceList)}
